const $=id=>document.getElementById(id);
const money=n=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR',maximumFractionDigits:0}).format(n);
function calculate(){const monthly=+$('monthly').value,years=+$('years').value,rate=+$('rate').value/1200;let total=0;const points=[0];for(let i=1;i<=years*12;i++){total=total*(1+rate)+monthly;if(i%12===0)points.push(total)}const principal=monthly*years*12;$('monthly-out').textContent=money(monthly);$('years-out').textContent=years+' years';$('rate-out').textContent=$('rate').value+'%';$('total').textContent=money(total);$('contributions').textContent=money(principal);$('earned').textContent=money(total-principal);const coords=points.map((v,i)=>`${i/years*500},${105-v/total*100}`);$('growth-line').setAttribute('d','M'+coords.join(' L'));$('area').setAttribute('d','M0,105 L'+coords.join(' L')+' L500,105 Z');$('principal-line').setAttribute('d',`M0,105 L500,${105-principal/total*100}`);$('chart').setAttribute('aria-label',`Over ${years} years, contributions total ${money(principal)}, with an illustrative accumulated value of ${money(total)}.`)}
if($('monthly')){['monthly','years','rate'].forEach(id=>$(id).addEventListener('input',calculate));calculate();}$('year').textContent=new Date().getFullYear();
document.querySelectorAll('[data-dialog]').forEach(button=>button.addEventListener('click',()=>$(button.dataset.dialog).showModal()));document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelectorAll('.close,.close-action').forEach(button=>button.addEventListener('click',()=>dialog.close()));dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}})});document.querySelectorAll('.print-button').forEach(button=>button.addEventListener('click',()=>window.print()));
const textButton=$('text-size'),contrastButton=$('contrast'),readButton=$('read-aloud'),readingStatus=$('reading-status');
function setPreference(key,on){document.body.classList.toggle(key,on);const button=key==='large-text'?textButton:contrastButton;button.setAttribute('aria-pressed',String(on));button.textContent=key==='large-text'?(on?'Standard text':'Larger text'):(on?'Standard contrast':'High contrast');try{localStorage.setItem('faircape-'+key,String(on))}catch{}}
['large-text','high-contrast'].forEach(key=>{try{setPreference(key,localStorage.getItem('faircape-'+key)==='true')}catch{}});
textButton.addEventListener('click',()=>{setPreference('large-text',!document.body.classList.contains('large-text'));readingStatus.textContent=document.body.classList.contains('large-text')?'Larger text enabled':'Standard text enabled'});
contrastButton.addEventListener('click',()=>{setPreference('high-contrast',!document.body.classList.contains('high-contrast'));readingStatus.textContent=document.body.classList.contains('high-contrast')?'High contrast enabled':'Standard contrast enabled'});
if('speechSynthesis' in window){readButton.hidden=false;let reading=false;function stopReading(){window.speechSynthesis.cancel();reading=false;readButton.textContent='Read this page aloud';readButton.setAttribute('aria-pressed','false')}readButton.addEventListener('click',()=>{if(reading){stopReading();return}const chunks=document.querySelector('main').innerText.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[];let index=0;reading=true;readButton.textContent='Stop reading';readButton.setAttribute('aria-pressed','true');function speakNext(){if(!reading||index>=chunks.length){stopReading();return}const utterance=new SpeechSynthesisUtterance(chunks[index++]);utterance.lang='en-ZA';utterance.rate=.9;utterance.onend=speakNext;utterance.onerror=()=>{stopReading();readingStatus.textContent='Read aloud is unavailable in this browser.'};window.speechSynthesis.speak(utterance)}speakNext()});window.addEventListener('pagehide',stopReading)}
const coastalFilm=$('coastal-film'),filmToggle=$('film-toggle');
if(coastalFilm&&filmToggle){filmToggle.hidden=false;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');let manuallyPaused=false;function updateFilm(){filmToggle.textContent=coastalFilm.paused?'Play coastal film':'Pause coastal film';coastalFilm.classList.toggle('is-playing',!coastalFilm.paused)}async function playFilm(){if(!coastalFilm.src)coastalFilm.src=coastalFilm.dataset.src;coastalFilm.muted=true;filmToggle.textContent='Loading film…';try{await coastalFilm.play();updateFilm()}catch{filmToggle.textContent='Play coastal film';$('film-status').textContent='The film could not play. The coastal photograph remains visible.'}}filmToggle.addEventListener('click',()=>{if(coastalFilm.paused){manuallyPaused=false;playFilm()}else{manuallyPaused=true;coastalFilm.pause()}});coastalFilm.addEventListener('pause',updateFilm);coastalFilm.addEventListener('playing',updateFilm);coastalFilm.addEventListener('error',()=>{coastalFilm.classList.remove('is-playing');filmToggle.textContent='Retry coastal film';$('film-status').textContent='Film unavailable. Showing the coastal photograph.'});reduced.addEventListener('change',e=>{if(e.matches)coastalFilm.pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden)coastalFilm.pause()});if(!reduced.matches&&!navigator.connection?.saveData&&window.innerWidth>760)playFilm();new IntersectionObserver(entries=>{if(!entries[0].isIntersecting)coastalFilm.pause()},{threshold:0}).observe(coastalFilm);}
